 90 | // resolveTarget returns owner, repo, and PR number from args.
 91 | func resolveTarget(args []string) (string, string, int, error) {
 92 | 	if len(args) == 0 {
 93 | 		return detectCurrentPR()
 94 | 	}
 95 | 
 96 | 	arg := args[0]
 97 | 
 98 | 	// Try as a number — requires current repo context
 99 | 	if n, err := strconv.Atoi(arg); err == nil {
100 | 		repo, err := repository.Current()
101 | 		if err != nil {
102 | 			return "", "", 0, fmt.Errorf("failed to determine repository: %w", err)
103 | 		}
104 | 		return repo.Owner, repo.Name, n, nil
105 | 	}
106 | 
107 | 	// Try as a URL containing /{owner}/{repo}/pull/{number}
108 | 	if u, err := url.Parse(arg); err == nil && u.Host != "" {
109 | 		parts := strings.Split(path.Clean(u.Path), "/")
110 | 		// parts: ["", owner, repo, "pull", number, ...]
111 | 		for i, p := range parts {
112 | 			if p == "pull" && i+1 < len(parts) && i >= 3 {
113 | 				if n, err := strconv.Atoi(parts[i+1]); err == nil {
114 | 					return parts[i-2], parts[i-1], n, nil
115 | 				}
116 | 			}
117 | 		}
118 | 	}
119 | 
120 | 	return "", "", 0, fmt.Errorf("invalid PR number or URL: %s", arg)
121 | }
