123 | func detectCurrentPR() (string, string, int, error) {
124 | 	stdout, _, err := gh.Exec("pr", "view", "--json", "number")
125 | 	if err != nil {
126 | 		return "", "", 0, fmt.Errorf("no PR found for current branch: %w", err)
127 | 	}
128 | 	var result struct {
129 | 		Number int `json:"number"`
130 | 	}
131 | 	if err := json.Unmarshal(stdout.Bytes(), &result); err != nil {
132 | 		return "", "", 0, fmt.Errorf("failed to parse PR info: %w", err)
133 | 	}
134 | 	if result.Number == 0 {
135 | 		return "", "", 0, fmt.Errorf("no PR found for current branch")
136 | 	}
137 | 
138 | 	repo, err := repository.Current()
139 | 	if err != nil {
140 | 		return "", "", 0, fmt.Errorf("failed to determine repository: %w", err)
141 | 	}
142 | 	return repo.Owner, repo.Name, result.Number, nil
143 | }

