129 | func (c *Client) MinimizeCopilotComments(prNumber int) (int, error) {
130 | 	var query struct {
131 | 		Repository struct {
132 | 			PullRequest struct {
133 | 				Reviews struct {
134 | 					Nodes []struct {
135 | 						ID          string `graphql:"id"`
136 | 						IsMinimized bool   `graphql:"isMinimized"`
137 | 						Author      struct {
138 | 							Login string
139 | 						}
140 | 					}
141 | 				} `graphql:"reviews(first: 100)"`
142 | 			} `graphql:"pullRequest(number: $number)"`
143 | 		} `graphql:"repository(owner: $owner, name: $repo)"`
144 | 	}
145 | 
146 | 	variables := map[string]any{
147 | 		"owner":  graphql.String(c.owner),
148 | 		"repo":   graphql.String(c.repo),
149 | 		"number": graphql.Int(int32(prNumber)), //nolint:gosec // PR numbers won't overflow int32
150 | 	}
151 | 
152 | 	err := c.gql.Query("CopilotReviewComments", &query, variables)
153 | 	if err != nil {
154 | 		return 0, fmt.Errorf("failed to query review comments: %w", err)
155 | 	}
156 | 
157 | 	var subjectIDs []string
158 | 	for _, review := range query.Repository.PullRequest.Reviews.Nodes {
159 | 		if !isCopilotUser(review.Author.Login) {
160 | 			continue
161 | 		}
162 | 		if !review.IsMinimized {
163 | 			subjectIDs = append(subjectIDs, review.ID)
164 | 		}
165 | 	}
166 | 
167 | 	minimized := 0
168 | 	for _, id := range subjectIDs {
169 | 		var mutation struct {
170 | 			MinimizeComment struct {
171 | 				MinimizedComment struct {
172 | 					IsMinimized bool
173 | 				}
174 | 			} `graphql:"minimizeComment(input: {subjectId: $id, classifier: OUTDATED})"`
175 | 		}
176 | 		vars := map[string]any{
177 | 			"id": graphql.ID(id),
178 | 		}
179 | 		if err := c.gql.Mutate("MinimizeComment", &mutation, vars); err != nil {
180 | 			fmt.Printf("Warning: failed to minimize comment %s: %v\n", id, err)
181 | 			continue
182 | 		}
183 | 		minimized++
184 | 	}
185 | 
186 | 	return minimized, nil
187 | }
